<main class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
  <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">Admin controls</p><h1 class="mt-2 text-3xl font-black">Tournaments</h1><p class="mt-2 text-sm text-slate-400">Create and manage entries, match details, room access and cancellations.</p></div><a class="btn-primary rounded-xl px-4 py-3 text-xs font-black" href="<?= h(app_url('index.php?page=admin-tournament-edit')) ?>"><i class="fa-solid fa-plus mr-2" aria-hidden="true"></i>New tournament</a></div>
  <form method="get" class="glass-card mt-5 flex flex-wrap items-end gap-3 rounded-2xl p-4"><input type="hidden" name="page" value="admin-tournaments"><label class="min-w-48 flex-1 text-xs font-bold text-slate-400">Search<input class="form-control mt-2" name="q" maxlength="80" value="<?= h($search) ?>" placeholder="Title or map"></label><label class="min-w-40 text-xs font-bold text-slate-400">Status<select class="form-control mt-2" name="status"><option value="all">All statuses</option><?php foreach(['draft','open','locked','live','completed','cancelled'] as $option): ?><option value="<?= h($option) ?>" <?= $statusFilter===$option?'selected':'' ?>><?= h(ucfirst($option)) ?></option><?php endforeach; ?></select></label><button class="btn-primary rounded-xl px-5 py-3 text-sm font-black">Filter</button></form>
  <div class="glass-card mt-5 overflow-hidden rounded-2xl">
    <?php if(!$tournaments): ?><p class="p-10 text-center text-sm text-slate-500">No tournaments match this search.</p><?php else: ?><div class="table-wrap"><table class="w-full text-left text-xs"><thead class="bg-black/20 text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-4">Tournament</th><th class="px-4 py-4">Mode</th><th class="px-4 py-4">Slots</th><th class="px-4 py-4">Prize / entry</th><th class="px-4 py-4">Match time</th><th class="px-4 py-4">Status</th><th class="px-4 py-4">Actions</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach($tournaments as $item): ?><tr><td class="px-4 py-4"><p class="font-black"><?= h($item['title']) ?></p><p class="mt-1 text-[10px] text-slate-500"><?= h($item['map_name']) ?> · #<?= h($item['id']) ?></p></td><td class="px-4 py-4 font-bold uppercase"><?= h($item['mode']) ?></td><td class="px-4 py-4"><?= h($item['occupied_slots']) ?> / <?= h($item['participant_limit']) ?></td><td class="px-4 py-4"><p class="font-bold text-neon-400"><?= h(format_money((int)$item['prize_pool_minor'])) ?></p><p class="mt-1 text-[10px] text-slate-500">Entry <?= h(format_money((int)$item['entry_fee_minor'])) ?></p></td><td class="px-4 py-4 text-[10px] text-slate-400"><?= h(date('d M Y · g:i A',strtotime((string)$item['match_time'].' UTC'))) ?> IST</td><td class="px-4 py-4"><span class="badge <?= $item['status']==='open'?'badge-open':($item['status']==='cancelled'?'badge-closed':'badge-soon') ?>"><?= h($item['status']) ?></span></td><td class="px-4 py-4"><div class="flex flex-wrap gap-2"><a class="rounded-lg border border-white/10 px-2.5 py-2 text-[10px] font-bold hover:bg-white/[.05]" href="<?= h(app_url('index.php?page=admin-tournament-edit&id='.(int)$item['id'])) ?>">Edit</a><a class="rounded-lg border border-violet-300/20 px-2.5 py-2 text-[10px] font-bold text-violet-200 hover:bg-violet-500/10" href="<?= h(app_url('index.php?page=admin-room&id='.(int)$item['id'])) ?>">Room</a><a class="rounded-lg border border-white/10 px-2.5 py-2 text-[10px] font-bold hover:bg-white/[.05]" href="<?= h(app_url('index.php?page=admin-results&id='.(int)$item['id'])) ?>">Results</a><?php if(!in_array($item['status'],['cancelled','completed'],true)): ?><form method="post" action="<?= h(app_url('index.php?action=admin-cancel-tournament')) ?>" data-confirm="Cancel this tournament? Confirmed entries will be refunded to the captain's wallet exactly once."><?= csrf_field() ?><input type="hidden" name="tournament_id" value="<?= h($item['id']) ?>"><button class="rounded-lg border border-rose-300/15 px-2.5 py-2 text-[10px] font-bold text-rose-300">Cancel</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <?php if($pageCount>1): ?><nav class="flex gap-2 border-t border-white/[.08] p-4" aria-label="Tournament pagination"><?php for($n=1;$n<=$pageCount;$n++): ?><a class="rounded-lg border px-3 py-2 text-xs <?= $n===$pageNumber?'border-violet-400/50 text-violet-200':'border-white/10 text-slate-400' ?>" href="<?= h(app_url('index.php?'.http_build_query(['page'=>'admin-tournaments','q'=>$search,'status'=>$statusFilter,'p'=>$n]))) ?>"><?= h($n) ?></a><?php endfor; ?></nav><?php endif; ?>
  </div>
</main>
